const team=DATA.chapters.find(c=>c.n===9);
Object.assign(team,{title:'The team approach to health care',category:'Operations',intro:'Use clear roles, closed loop communication, and shared situational awareness on an EMS call.',pending:false,provisional:true,takeaway:'One clinician leads, but everyone watches for change, speaks up, and confirms critical tasks.',deep:[
 ['Roles and shared goal','An EMS response is a team effort with a shared patient care goal. A leader assigns roles for assessment, airway, treatment, equipment, communication, and transport as needed. Roles can change as patient needs change; the patient should not be left without a clear reassessment owner.','Before a complex move or resuscitation, state the plan aloud. A team member who sees a threat should speak up even when someone else is leading.'],
 ['Closed loop communication','Give a specific instruction to a named teammate, have it acknowledged, and confirm completion or report a problem. “Ari, bring the BVM” followed by “BVM here” is more reliable than a general shout into a noisy scene.','Use concise reports with patient condition, action, and response. Repeat back drug, dose, destination, or another critical instruction when misunderstanding could harm the patient.'],
 ['Situational awareness and crew resource management','Keep track of the patient, scene, time, equipment, partner workload, and transport options. Avoid tunnel vision on one procedure. A team member can call attention to a new airway problem, changing vital trend, or missed hazard.','Use all available resources: a partner, a bystander who can provide history, medical direction, or additional responders. Escalate early when the team or equipment cannot safely meet the task.'],
 ['Handoff and transitions','When another crew or clinician assumes care, state the chief complaint, relevant history, primary findings, vital trends, interventions, response, and unfinished tasks. Say who has responsibility for the patient during a move or transfer.','A good handoff is a conversation. Invite readback of high risk details and correct discrepancies immediately.'],
 ['Assisting higher level care','An EMT may support an advanced clinician by preparing equipment, monitoring the patient, continuing basic care, and reporting changes within training and local protocol. Anticipate needs but never perform a skill outside your authorized scope.','Keep the basic priorities going during an advanced procedure: airway, ventilation, circulation, scene safety, and repeated reassessment.']
],practical:{why:'Good team behavior prevents missed threats and unclear ownership when a call becomes busy.',workflow:['Name a leader and assign assessment, airway, equipment, and documentation roles.','State the immediate priority and transport plan aloud.','Use named requests and confirmation that the task was completed.','Invite concerns from all teammates and update the plan when the patient changes.','Give a structured handoff with trends and outstanding tasks.'],red:['No one owns reassessment during a procedure.','A critical request is made but never acknowledged.','The patient deteriorates while the team is focused on one task.'],mistakes:['Assuming silence means a task was completed.','Ignoring a junior teammate who identifies a new threat.','Losing track of airway and ventilation while assisting a procedure.'],scenario:'During BVM support, a teammate reports that chest rise has stopped. The leader pauses the current plan, confirms the finding, assigns seal and airway correction, and asks for immediate reassessment.',challenge:{prompt:'Your crew is focused on equipment setup. A teammate says the patient is now barely breathing, but no one responds. What is the best team action?',options:['Assume the leader heard it and continue setup','Repeat the concern clearly, redirect to airway and ventilation, and confirm an assigned response','Wait until the procedure is complete','Document it later without interrupting'],right:1,why:'A new life threat requires clear closed loop communication and an immediate assigned response.'}}});
DATA.cards.push(...[
[9,'What is closed loop communication?','A named request, acknowledgment, and confirmation of completion or a problem.'],
[9,'Who can raise a concern about a new threat?','Any team member who observes it.'],
[9,'What should a team leader assign?','Clear roles for assessment, care, equipment, transport, and reassessment.'],
[9,'What is situational awareness?','Tracking patient, scene, resources, team workload, and changes in time.'],
[9,'What should a handoff include?','Complaint, key history and findings, trends, care, response, and unfinished tasks.'],
[9,'Can an EMT perform an ALS skill just because asked?','Only if within training, scope, and local authorization.'],
[9,'What if a critical request is not acknowledged?','Repeat and confirm it with a named teammate.'],
[9,'Why announce a change in the plan?','So every teammate knows the new priority and their role.']
]);
DATA.extraQuestions.push(...[
[9,1,'Communication','What completes a closed loop request?',['A teammate confirms the task was done or reports a problem','A request is shouted once','The leader assumes it happened','Only a written note'],0,'Confirmation closes the loop.'],
[9,1,'Team roles','Who should report a newly detected life threat?',['Any teammate who sees it','Only the designated leader','Only a paramedic','Only dispatch'],0,'All team members contribute to patient safety.'],
[9,1,'Scope','When can an EMT assist an advanced procedure?',['Within training, scope, and protocol','Whenever asked by any bystander','Only after transport','Without monitoring the patient'],0,'Authorized scope still applies in team care.'],
[9,2,'Communication','A leader asks for suction but no one acknowledges. What is the best next step?',['Repeat the request to a named teammate and confirm completion','Assume it is coming','Leave the patient to search silently','Wait for deterioration'],0,'A named, acknowledged request reduces missed tasks.'],
[9,2,'Team roles','During a complex move, nobody is watching the patient’s breathing. What should the leader do?',['Assign a clinician to airway and reassessment','Focus only on equipment','Assume the patient is stable','Complete paperwork'],0,'Critical monitoring needs explicit ownership.'],
[9,2,'Handoff','Which report best transfers care?',['Findings and trends, actions, response, and pending tasks','Only the patient’s name','Only the last SpO₂','Only the dispatch complaint'],0,'Handoff should carry the relevant clinical timeline.'],
[9,3,'Situational awareness','A teammate notices worsening chest rise while the crew prepares a device. What should happen?',['State the change, reprioritize ventilation, and assign the next action','Finish the setup first regardless','Ignore it because the monitor is normal','Wait for transport'],0,'Situational awareness includes redirecting to a new life threat.'],
[9,3,'Communication','Two teammates believe the other gave an ordered treatment. No one can confirm it. Best response?',['Verify whether it happened before repeating or documenting it','Document it as done','Give another dose without checking','Ignore the discrepancy'],0,'Confirm the task and avoid duplicate treatment or inaccurate documentation.']
].map(([n,level,topic,prompt,options,right,why],i)=>({n,level,topic,prompt,options,right,why,id:'team'+i})));
